    if not input_data:
        return
    n = int(input_data[0])
    p = input_data[1]

    # Contagem total de caracteres
    total_counts = [0] * 26
    for ch in p:
        total_counts[ord(ch) - 97] += 1

    # Encontrar todos os divisores de n menores que n
    divisors = []
