                divisors.append(n // d)
    divisors.sort()

    for L in divisors:
        k = n // L  # número de blocos (k >= 2)

        # Condição necessária: total_counts de cada caractere deve ser divisível por k
        possible = True
        target = [0] * 26
        for c in range(26):
            if total_counts[c] % k != 0:
                possible = False
                break
            target[c] = total_counts[c] // k

        if not possible:
            continue

        # Verificar se cada bloco de tamanho L possui exatamente as contagens de target
        valid = True
        for i in range(k):
            block = p[i * L : (i + 1) * L]
            block_counts = [0] * 26
            for ch in block:
                block_counts[ord(ch) - 97] += 1
            if block_counts != target:
                valid = False
                break

        if valid:
            print(p[:L])
            return

    print('*')

if __name__ == '__main__':
